class Cart:
    def __init__(self, free_shipping_threshold: float = 100.0, shipping_cost: float = 15.0) -> None:
        self.free_shipping_threshold = free_shipping_threshold
        self.shipping_cost = shipping_cost
        self.items = []  # list of (name, unit_price, quantity)
        self.discounts = []  # list of percent values
        self.vouchers = []   # list of fixed amounts

    def add(self, name: str, unit_price: float, quantity: int = 1) -> None:
        if quantity <= 0:
            raise ValueError("Quantity must be positive")
        if unit_price < 0:
            raise ValueError("Unit price must be non-negative")
        self.items.append((name, unit_price, quantity))

    def apply_discount(self, percent: float) -> None:
        self.discounts.append(percent)

    def apply_voucher(self, amount: float) -> None:
        self.vouchers.append(amount)

    def total(self) -> float:
        items_value = sum(price * qty for _, price, qty in self.items)

        # Compute best saving: either a discount percent or a voucher amount.
        best_saving = 0.0

        # Discount savings are computed on items_value.
        for percent in self.discounts:
            saving = items_value * (percent / 100.0)
            if saving > best_saving:
                best_saving = saving

        # Voucher savings: fixed amount, capped at items_value (voucher never makes price negative).
        for amount in self.vouchers:
            saving = min(amount, items_value)
            if saving > best_saving:
                best_saving = saving

        items_after = items_value - best_saving
        if items_after < 0:
            items_after = 0.0

        # Free shipping check against value before discounts.
        if items_value >= self.free_shipping_threshold:
            shipping = 0.0
        else:
            shipping = self.shipping_cost

        return items_after + shipping
